window.AUTH=window.AUTH||{};window.AUTH["24-820"]={"d":"24-820","id":"2025/24-820","n":"Rutherford v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Daniel Rutherford","date":"2025-08-08","url":"https://www.supremecourt.gov/DocketPDF/24/24-820/369264/20250808153852666_opening%20merits%20brief%20-%20Rutherford%20v.%20U.S.%20-%20No.%2024-820.pdf","side":"pet","n":134},{"k":"petitioner","label":"Brief of petitioner Johnnie Markel Carter","date":"2025-08-08","url":"https://www.supremecourt.gov/DocketPDF/24/24-820/369300/20250808184320866_No.%2024-860_Brief.pdf","side":"pet","n":47},{"k":"respondent","label":"Brief of respondent United States","date":"2025-09-25","url":"https://www.supremecourt.gov/DocketPDF/24/24-820/377956/20250925182237138_24-820bsUnitedStates.pdf","side":"res","n":76},{"k":"reply","label":"Reply of petitioner Daniel Rutherford","date":"2025-10-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-820/380752/20251027164806568_merits%20reply%20brief%20-%20Rutherford%20v.%20U.S.%20-%20No.%2024-820.pdf","side":"pet","n":60},{"k":"reply","label":"Reply of petitioner Johnnie Markel Carter","date":"2025-10-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-820/380758/20251027172028724_24-860_Reply%20Brief.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us2r40_o7kq.pdf","tr":true,"items":[{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"by":{"0":"3"}},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"by":{"0":"47-48"}},{"t":"case","label":"Board of Pardons v. Allen","cite":"482 U.S. 369","y":1987,"id":"1986/86-461","sc":1,"by":{"0":"26"}},{"t":"case","label":"Bourjaily v. United States","cite":"483 U.S. 171","y":1987,"id":"1986/85-6725","sc":1,"by":{"0":"33"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"[T]he only authoritative source of statutory meaning is the text that has passed through the Article I process.","cite":"562 U.S. 223, 242 n.72"}]},{"t":"case","label":"Buck v. Davis","cite":"580 U.S. 100","y":2017,"id":"2016/15-8049","sc":1,"by":{"0":"28"}},{"t":"case","label":"Bullington v. Missouri","cite":"451 U.S. 430","y":1981,"id":"1980/79-6740","sc":1,"by":{"0":"26"}},{"t":"case","label":"Cagle v. Harris","cite":"349 F.2d 404","y":1965,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/349/404/","by":{"0":"26"}},{"t":"case","label":"Center for Auto Safety v. Chrysler Grp., LLC","cite":"809 F.3d 1092","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/809/1092/","by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"[w]hat constitutes a compelling reason is best left to the sound discretion of the trial court.","cite":"809 F.3d 1092, 1097"}]},{"t":"case","label":"Concepcion v. United States","cite":"597 U.S. 481","y":2022,"id":"2021/20-1650","sc":1,"by":{"0":"1, 10, 22-23, 25, 37-39, 47, 49","1":"23, 27,47–48","2":"36","3":"1, 3, 4, 7, 9, 12, 13, 15","4":"6–7, 9, 22"},"q":[{"src":"brief","b":0,"text":"later proceedings that may modify an original sentence.","cite":"597 U.S. 481, 490-91"},{"src":"brief","b":0,"text":"requir[es] courts to abide by the Sentencing Commission’s policy statements.","cite":"597 U.S. 481, 495"},{"src":"brief","b":1,"text":"sentencing judges ‘enjo[y] discretion in the sort of information they may consider.","cite":"597 U.S. at 491"},{"src":"brief","b":3,"text":"That unbroken tradition characterizes federal sentencing history as well.","cite":"597 U.S. at 492"},{"src":"brief","b":3,"text":"[i]t is only when Congress or the Constitution limits the scope of information that a district court may consider in deciding whether, and to what extent, to modify a sentence, that a district court’s discretion to consider information is restrained.","cite":"597 U.S. at 486"},{"src":"brief","b":4,"text":"very purpose is to reopen final judgments,","cite":"597 U.S. 481, 491 n.3"},{"src":"brief","b":4,"text":"Congress or the Constitution expressly limits","cite":"597 U.S. at 491"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"broad discretion to consider all relevant information","cite":"597 U. S. 481, 491"},{"src":"argument","who":"Mr. O'Neil","text":"The fourth is the Concepcion principle. You start with the premise that Congress meant district courts to have the broadest possible discretion unless the Constitution or -- or Congress explicitly limits it."},{"src":"argument","who":"Justice Jackson","text":"My understanding through Concepcion and also experience is that that's not exactly how it works. The court is looking at the totality of the circumstances."}]},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"by":{"0":"6","2":"8"}},{"t":"case","label":"Dean v. United States","cite":"581 U.S. 62","y":2017,"id":"2016/15-9260","sc":1,"by":{"0":"21, 25, 37-38","1":"48","2":"36, 37","3":"7, 15, 19","4":"7"}},{"t":"case","label":"Deputy v. du Pont","cite":"308 U.S. 488","y":1940,"id":"scdb/1939-103","sc":1,"by":{"0":"17"}},{"t":"case","label":"Dillon v. United States","cite":"560 U.S. 817","y":2010,"id":"2009/09-6338","sc":1,"by":{"0":"22, 49","1":"21, 23, 28","2":"6, 19","3":"10, 12"},"q":[{"src":"brief","b":1,"text":"follow the Commission’s instructions . . . to determine [a] prisoner’s eligibility for a sentence modification.","cite":"560 U.S. at 827"},{"src":"brief","b":2,"text":"established the Sentencing Commission and authorized it to promulgate Sentencing Guidelines and to issue policy statements.","cite":"560 U.S. 817, 820"},{"src":"brief","b":2,"text":"A federal court generally ‘may not modify a term of imprisonment once it has been imposed.’","cite":"560 U.S. 817, 819"}]},{"t":"case","label":"District of Columbia v. Wesby","cite":"583 U.S. 48","y":2018,"id":"2017/15-1485","sc":1,"by":{"0":"33-34","1":"44","2":"48","3":"5"},"q":[{"src":"brief","b":0,"text":"that the whole is often greater than the sum of its parts—especially when the parts are viewed in isolation.","cite":"583 U.S. 48, 60-61"},{"src":"brief","b":1,"text":"the whole is often greater than the sum of its parts—especially when the parts are viewed in isolation.","cite":"583 U.S. 48, 60–61"},{"src":"brief","b":2,"text":"the whole is often greater than the sum of its parts,","cite":"583 U.S. 48, 60-61"}]},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"by":{"0":"31-32","2":"22"},"q":[{"src":"brief","b":0,"text":"‘in federal sentencing the ordinary practice is to apply new penalties to defendants not yet sentenced, while withholding that change from defendants already sentenced.’","cite":"567 U.S. at 280"},{"src":"brief","b":2,"text":"withholding that change from defendants already sentenced.","cite":"567 U.S. at 280"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"withhol[d] that change from defendants already sentenced.","cite":"567 U. S. 260, 280"},{"src":"argument","who":"Mr. Feigin","text":"Well, the crack offense retroactivity was actually making up for a -- a loop -- not a loophole but a problem it perceived after the Fair Sentencing Act, where it -- as the Court discussed in Dorsey, it had made the changes effective from that day forward, essentially, exactly what Congress then decided to do in 403(b) and was making up for that for the set of prisoners who were still in prison for those offenses."}]},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"by":{"0":"39, 42","2":"43","3":"15"},"q":[{"src":"brief","b":0,"text":"Respect for Congress as drafter counsels against too easily finding irreconcilable conflicts in its work.","cite":"584 U.S. at 511"}]},{"t":"case","label":"Esteras v. United States","cite":"145 S. Ct. 2031","y":2025,"id":"2024/23-7483","sc":1,"by":{"0":"16, 20, 24, 34","3":"1, 3, 6, 9, 10, 11, 9","4":"28"},"q":[{"src":"brief","b":0,"text":"might lead to a different result altogether,","cite":"145 S. Ct. 2031, 2043"},{"src":"brief","b":0,"text":"might lead to a different result altogether.","cite":"145 S. Ct. at 2042"},{"src":"brief","b":3,"text":"might lead to a different result altogether.","cite":"145 S. Ct. at 2043"},{"src":"brief","b":3,"text":"is not limited to the initial imposition of a sentence, but also ‘carries forward to later proceedings that may modify’","cite":"145 S. Ct. at 2042"},{"src":"brief","b":4,"text":"Silence is an unusual way to convey such an instruction.","cite":"145 S. Ct. 2031, 2040 n.4"}]},{"t":"case","label":"Florida v. Harris","cite":"568 U.S. 237","y":2013,"id":"2012/11-817","sc":1,"by":{"0":"17","3":"5"},"q":[{"src":"brief","b":0,"text":"in favor of a more flexible, all-things-considered approach,","cite":"568 U.S. 237, 244"},{"src":"brief","b":3,"text":"in favor of a more flexible, all-things-considered approach,","cite":"568 U.S. 237, 244"}]},{"t":"case","label":"Gall v. United States","cite":"552 U.S. 38","y":2007,"id":"2007/06-7949","sc":1,"by":{"0":"18"},"q":[{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"begin all sentencing proceedings by correctly calculating the applicable Guidelines range,","cite":"552 U. S. 38, 49"}]},{"t":"case","label":"Garner v. Jones","cite":"529 U.S. 244","y":2000,"id":"1999/99-137","sc":1,"by":{"0":"26"}},{"t":"case","label":"Graham v. Florida","cite":"560 U.S. 48","y":2010,"id":"2009/08-7412","sc":1,"by":{"0":"18"}},{"t":"case","label":"Greenholtz v. Inmates of Nebraska Penal & Corr. Complex","cite":"442 U.S. 1","y":1979,"id":"1978/78-201","sc":1,"by":{"0":"26"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"by":{"0":"36, 43","3":"19"},"q":[{"src":"brief","b":0,"text":"cannot replace the actual text with speculation as to Congress’ intent.","cite":"582 U.S. 79, 89"},{"src":"brief","b":0,"text":"might have done had it faced a question that . . . it never faced.","cite":"582 U.S. at 89"},{"src":"brief","b":3,"text":"job to rewrite a constitutionally valid statutory text.","cite":"582 U.S. 79, 89"}]},{"t":"case","label":"Hertz v. Woodman","cite":"218 U.S. 205","y":1910,"id":"scdb/1909-175","sc":1,"by":{"0":"45-46"},"q":[{"src":"brief","b":0,"text":"a remission of penalties and forfeitures dependent upon the destroyed statute.","cite":"218 U.S. 205, 216"}]},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"by":{"0":"33"}},{"t":"case","label":"Jones v. Bock","cite":"549 U.S. 199","y":2007,"id":"2006/05-7058","sc":1,"by":{"0":"47","3":"19, 22"},"q":[{"src":"brief","b":0,"text":"on the basis of perceived policy concerns.","cite":"549 U.S. 199, 212, 216"},{"src":"brief","b":3,"text":"on the basis of perceived policy concerns.","cite":"549 U.S. 199, 212, 216"}]},{"t":"case","label":"Kemp v. United States","cite":"596 U.S. 528","y":2022,"id":"2021/21-5726","sc":1,"by":{"0":"17, 28"}},{"t":"case","label":"Kimbrough v. United States","cite":"552 U.S. 85","y":2007,"id":"2007/06-6330","sc":1,"by":{"0":"3, 36","1":"3, 37, 47–48","3":"6, 7","4":"7"},"q":[{"src":"brief","b":0,"text":"to formulate and constantly refine national sentencing standards,","cite":"552 U.S. 85, 108"},{"src":"brief","b":0,"text":"Congress has shown that it knows how to direct sentencing practices in express terms.","cite":"552 U.S. 85, 103"},{"src":"brief","b":1,"text":"formulate and constantly refine national sentencing standards.","cite":"552 U.S. 85, 108"},{"src":"brief","b":1,"text":"Congress has shown that it knows how to direct sentencing practices in express terms.","cite":"552 U.S. at 103"},{"src":"brief","b":3,"text":"knows how to direct sentencing practices in express terms.","cite":"552 U.S. 85, 103"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"`shown that it knows how to direct sentencing practices in express terms.'","cite":"552 U. S. 85, 103"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"constrained by the mandatory minimums Congress prescribed","cite":"552 U. S., at 101, 108"},{"src":"argument","who":"Mr. O'Neil","text":"The third is the rule from Kimbrough, we're dealing with a sentencing statute. Congress has said Congress -- excuse me -- this Court has said Congress knows how to direct sentencing practices in express terms and has shown that it has done so."}]},{"t":"case","label":"Koon v. United States","cite":"518 U.S. 81","y":1996,"id":"1995/94-1664","sc":1,"by":{"0":"31-32, 35-36","1":"15, 39","3":"13, 19","4":"28"},"q":[{"src":"brief","b":0,"text":"embodies the traditional exercise of discretion by a sentencing court.","cite":"518 U.S. 81, 98"},{"src":"brief","b":1,"text":"for the courts to conclude a factor must not be considered under any circumstances would be to transgress the policymaking authority vested in the Commission.","cite":"518 U.S. 81, 106–07"},{"src":"brief","b":1,"text":"grant federal courts authority to decide what sorts of sentencing considerations are inappropriate in every circumstance.","cite":"518 U.S. at 106"},{"src":"brief","b":3,"text":"Congress did not grant federal courts authority to decide what sorts of sentencing considerations are inappropriate in every circumstance.","cite":"518 U.S. 81, 106"},{"src":"brief","b":3,"text":"consider every convicted person as an individual and every case as a unique study in the human failings that sometimes mitigate, sometimes magnify, the crime and the punishment to ensue.","cite":"518 U.S. at 113"},{"src":"brief","b":4,"text":"did not grant federal courts authority to decide what sorts of sentencing considerations are inappropriate in every circumstance.","cite":"518 U.S. 81, 106"}]},{"t":"case","label":"Kugler v. Helfant","cite":"421 U.S. 117","y":1975,"id":"1974/74-80","sc":1,"by":{"0":"15, 48","1":"25","3":"4"},"q":[{"src":"brief","b":0,"text":"makes it impossible to anticipate and define every situation that might","cite":"421 U.S. 117, 124"}]},{"t":"case","label":"Liljeberg v. Health Servs. Acquisition Corp.","cite":"486 U.S. 847","y":1988,"id":"1987/86-957","sc":1,"by":{"0":"17"}},{"t":"case","label":"Metropolitan Stevedore Co. v. Rambo","cite":"515 U.S. 291","y":1995,"id":"1994/94-820","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"suggests that Congress did not intend to limit the bases for [relief ] to a single condition.","cite":"515 U.S. 291, 296"}]},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"by":{"0":"3","1":"3–4, 13–14, 27, 30, 33–34","2":"5, 45, 46","4":"25–26"},"q":[{"src":"brief","b":1,"text":"precisely the sort of intricate, labor-intensive task for which delegation to an expert body is especially appropriate,","cite":"488 U.S. at 379"},{"src":"brief","b":1,"text":"a peculiar institution within the framework of our Government.","cite":"488 U.S. at 384"},{"src":"brief","b":2,"text":"uncertainty as to the time the offender would spend in prison","cite":"488 U.S. 361, 363, 366"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"[b]oth indeterminate sentencing and parole were based on concepts of the offender's possible, indeed Page Proof Pending Publication probable, rehabilitation, a view that it was realistic to attempt to rehabilitate the inmate and thereby to minimize the risk that he would resume criminal activity upon his return to society.","cite":"488 U. S. 361, 363"}]},{"t":"case","label":"National Ass’n of Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"by":{"0":"39"}},{"t":"case","label":"Octane Fitness, LLC v. ICON Health & Fitness, Inc.","cite":"572 U.S. 545","y":2014,"id":"2013/12-1184","sc":1,"by":{"0":"16-17, 34, 48","3":"4"},"q":[{"src":"brief","b":0,"text":"superimpose[d] an inflexible framework onto statutory text that is inherently flexible.","cite":"572 U.S. at 554"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"`[t]here is no precise rule or formula for making these determinations.'","cite":"572 U. S. 545, 554"}]},{"t":"case","label":"Ohio v. Robinette","cite":"519 U.S. 33","y":1996,"id":"1996/95-891","sc":1,"by":{"0":"17","3":"4"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"by":{"0":"23, 34","1":"28","3":"1, 3, 5, 8, 19","4":"25"},"q":[{"src":"brief","b":0,"text":"expressly preserved the traditional discretion of sentencing courts to ‘conduct an inquiry broad in scope, largely unlimited either as to the kind of information they may consider, or the source from which it may come.’","cite":"562 U.S. 476, 489"},{"src":"brief","b":0,"text":"consider the widest possible breadth of information about a defendant,","cite":"562 U.S. at 488"},{"src":"brief","b":1,"text":"The Commission has comparatively greater ability [than an individual judge] to gather information, to consider a broader national picture, . . . and ultimately to write more coherent overall standards that reflect nationally uniform . . . sentencing policies.","cite":"562 U.S. 476, 513"},{"src":"brief","b":1,"text":"Congress delegated to the Sentencing Commission the authority to make policy decisions regarding federal sentencing.","cite":"562 U.S. at 516"},{"src":"brief","b":3,"text":"does not provide ‘any basis for the courts to invent a blanket prohibition against considering certain types of evidence at sentencing.’","cite":"562 U.S. at 491"},{"src":"brief","b":3,"text":"resentencing after a prior sentence has been set aside on appeal,","cite":"562 U.S. at 491"},{"src":"brief","b":4,"text":"nationally uniform . . . sentencing policies,","cite":"562 U.S. 476, 513"}]},{"t":"case","label":"Posadas v. National City Bank of New York","cite":"296 U.S. 497","y":1936,"id":"scdb/1935-071","sc":1,"by":{"0":"40"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"by":{"0":"44"}},{"t":"case","label":"Public Emps. Ret. Sys. of Ohio v. Betts","cite":"492 U.S. 158","y":1989,"id":"1988/88-389","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"did not change the controlling, general language of the statute.","cite":"492 U.S. 158, 168"}]},{"t":"case","label":"Radzanower v. Touche Ross & Co.","cite":"426 U.S. 148","y":1976,"id":"1975/75-268","sc":1,"by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"they are not so repugnant to each other as to justify a finding of implied repeal.","cite":"426 U.S. at 156"}]},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"by":{"0":"37, 39, 47","2":"36, 37","3":"15, 19"},"q":[{"src":"brief","b":0,"text":"no legislation pursues its purposes at all costs.","cite":"480 U.S. at 525"},{"src":"brief","b":3,"text":"[N]o legislation pursues its purposes at all costs.","cite":"480 U.S. at 525"}]},{"t":"case","label":"Sampson v. Murray","cite":"415 U.S. 61","y":1974,"id":"1973/72-403","sc":1,"by":{"0":"16, 48"},"q":[{"src":"brief","b":0,"text":"extraordinary cases are hard to define in advance of their occurrence,","cite":"415 U.S. 61, 92 n.68"}]},{"t":"case","label":"Setser v. United States","cite":"566 U.S. 231","y":2012,"id":"2011/10-7387","sc":1,"by":{"0":"28","2":"39","3":"13, 14"},"q":[{"src":"brief","b":0,"text":"a significantly longer sentence than those of his codefendants.","cite":"566 U.S. 231"}]},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"ambiguity concerning the ambit of criminal statutes should be resolved in favor of","cite":"561 U.S. 358, 410"}]},{"t":"case","label":"State v. Reeder","cite":"60 S.E. 434","y":1908,"court":"S.C.","url":"https://www.courtlistener.com/c/S.E./60/434/","by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"mind can be enlightened should not be prohibited to him,","cite":"60 S.E. at 435"}]},{"t":"case","label":"State Farm Fire & Cas. Co. v. U.S. ex rel. Rigsby","cite":"580 U.S. 264","y":2016,"id":"2016/15-513","sc":1,"by":{"0":"21"}},{"t":"case","label":"Sure-Tan, Inc. v. NLRB","cite":"467 U.S. 883","y":1984,"id":"1983/82-945","sc":1,"by":{"0":"29"}},{"t":"case","label":"Tapia v. United States","cite":"564 U.S. 319","y":2011,"id":"2010/10-5400","sc":1,"by":{"0":"27","2":"5, 6, 37"}},{"t":"case","label":"United States v. Andrews","cite":"12 F.4th 255","y":2021,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/12/255/","by":{"0":"5, 9-10, 42, 48","1":"6, 11","2":"9, 12"},"q":[{"src":"brief","b":0,"text":"suggest[s] that [§ 403’s] non-retroactive amendments ‘simultaneously created an extraordinary and compelling reason for early release.’","cite":"12 F.4th 255, 261"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"`construe Congress's nonretroactivity directive as simultaneously creating an extraordinary and compelling reason for early release.'","cite":"12 F. 4th, at 261"}]},{"t":"case","label":"United States v. Angelos","cite":"345 F. Supp. 2d 1227","y":2004,"court":"D. Utah","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/345/1227/","by":{"0":"18-19"},"q":[{"src":"brief","b":0,"text":"one of those rare cases where the system has malfunctioned. . . . The 55-year sentence mandated by § 924(c) in this case appears to be unjust, cruel, and irrational.","cite":"345 F. Supp. 2d 1227, 1261-63"}]},{"t":"case","label":"United States v. Arvizu","cite":"534 U.S. 266","y":2002,"id":"2001/00-1519","sc":1,"by":{"0":"33"}},{"t":"case","label":"United States v. Bradley","cite":"97 F.4th 1214","y":2024,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/97/1214/","by":{"0":"31"}},{"t":"case","label":"United States v. Brooker","cite":"976 F.3d 228","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/976/228/","by":{"0":"4","1":"41, 45","4":"14"}},{"t":"case","label":"United States v. Chen","cite":"48 F.4th 1092","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/48/1092/","by":{"0":"38-39, 41, 43","3":"8"},"q":[{"src":"brief","b":0,"text":"that district courts cannot consider non-retroactive changes in sentencing law would be to create a categorical bar against a particular factor, which Congress itself has not done.","cite":"48 F.4th 1092, 1098"},{"src":"brief","b":3,"text":"[t]hrough § 3582(c)(1)(A) and § 994(t), Congress has demonstrated that it can, and will, directly limit what constitutes extraordinary and compelling reasons,","cite":"48 F.4th 1092, 1099"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"[I]f Congress truly intended to bar district courts from considering [the First Step Act's] changes to mandatory minimums in the compassionate release context by making the changes nonretroactive, then it is doubtful those changes should be considered at all.","cite":"48 F. 4th 1092, 1099"}]},{"t":"case","label":"United States v. Davis","cite":"961 F.3d 181","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/961/181/","by":{"0":"41"}},{"t":"case","label":"United States v. Diaco","cite":"457 F. Supp. 371","y":1978,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./457/371/","by":{"0":"28","3":"13, 20, 21","4":"19–20"},"q":[{"src":"brief","b":0,"text":"a significantly longer sentence than those of his codefendants.","cite":"457 F. Supp. 371, 372"},{"src":"brief","b":3,"text":"[i]n view of this disparity, the sentencing court may wish to act to reduce","cite":"457 F. Supp. at 372"},{"src":"argument","who":"Mr. Frederick","text":"And we know that because the Diaco case, the Bureau of Prisons, represented by the Department of Justice, came to court and said the long sentence should be reduced because of these disparate circumstances."}]},{"t":"case","label":"United States v. Dominguez","cite":"296 F.3d 192","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/296/192/","by":{"0":"16","1":"44"},"q":[{"src":"brief","b":0,"text":"committed to the sound discretion of the sentencing court,","cite":"296 F.3d 192, 195-96"},{"src":"brief","b":1,"text":"take a case out of the ordinary.","cite":"296 F.3d 192, 196"}]},{"t":"case","label":"United States v. Fior D’Italia, Inc.","cite":"536 U.S. 238","y":2002,"id":"2001/01-463","sc":1,"by":{"0":"16"}},{"t":"case","label":"United States v. Goodwin","cite":"486 F.3d 449","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/486/449/","by":{"0":"18"}},{"t":"case","label":"United States v. Hinton","cite":"2022 WL 988372","y":2022,"court":"E.D. Va. Mar. 31","by":{"0":"19"}},{"t":"case","label":"United States v. Honken","cite":"184 F.3d 961","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/184/961/","by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"no magic formula for defining an ‘extraordinary case,’","cite":"184 F.3d 961, 969"}]},{"t":"case","label":"United States v. Hungerford","cite":"465 F.3d 1113","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/465/1113/","by":{"0":"19"}},{"t":"case","label":"United States v. Hunter","cite":"770 F.3d 740","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/770/740/","by":{"0":"19"}},{"t":"case","label":"United States v. Hunter","cite":"12 F.4th 555","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/12/555/","by":{"0":"48"}},{"t":"case","label":"United States v. Jarvis","cite":"999 F.3d 442","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/999/442/","by":{"0":"43","2":"47","3":"6"},"q":[{"src":"brief","b":2,"text":"adding a legally impermissible ground to three insufficient factual considerations does not entitle a defendant to a sentence reduction.","cite":"999 F.3d 442, 444"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"[A]dding a legally impermissible ground to three insuffcient factual considerations does not entitle a defendant to a sentence reduction.","cite":"999 F. 3d 442, 444"}]},{"t":"case","label":"United States v. Johnson","cite":"529 U.S. 53","y":2000,"id":"1999/98-1696","sc":1,"by":{"0":"21","1":"49"},"q":[{"src":"brief","b":0,"text":"When Congress provides exceptions in a statute, it does not follow that courts have authority to create others.","cite":"529 U.S. 53, 58"}]},{"t":"case","label":"United States v. Maumau","cite":"993 F.3d 821","y":2021,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/993/821/","by":{"0":"31"}},{"t":"case","label":"United States v. McCall","cite":"56 F.4th 1048","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/56/1048/","by":{"0":"43-44, 47-48","2":"24"},"q":[{"src":"brief","b":0,"text":"provide an end run around habeas.","cite":"56 F.4th at 1058"}]},{"t":"case","label":"United States v. McKinnie","cite":"24 F.4th 583","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/24/583/","by":{"0":"48"}},{"t":"case","label":"United States v. Moody","cite":"115 F.4th 304","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/115/304/","by":{"0":"31"}},{"t":"case","label":"United States v. Myers","cite":"2021 WL 2401237","y":2021,"court":"D. Md. June 11","by":{"0":"19"}},{"t":"case","label":"United States v. Reisinger","cite":"128 U.S. 398","y":1888,"id":"scdb/1888-043","sc":1,"by":{"0":"47"}},{"t":"case","label":"United States v. Rivera-Ruperto","cite":"852 F.3d 1","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/852/1/","by":{"0":"19"}},{"t":"case","label":"United States v. Rodriguez","cite":"451 F. Supp. 3d 392","y":2020,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/451/392/","by":{"0":"48"}},{"t":"case","label":"United States v. Rodriguez","cite":"2024 WL 5119901","y":2024,"court":"D.N.M. Dec. 16","by":{"0":"19"}},{"t":"case","label":"United States v. Rutherford","cite":"236 F. App’x 835","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/236/835/","by":{"0":"8, 18-19"}},{"t":"case","label":"United States v. Ruvalcaba","cite":"26 F.4th 14","y":2022,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/26/14/","by":{"0":"24, 41-43"},"q":[{"src":"brief","b":0,"text":"fits seamlessly with the history and purpose of the compassionate-release statute.","cite":"26 F.4th 14, 26"},{"src":"brief","b":0,"text":"is not sullied by a district court’s determination, on a case-by-case basis, that a particular defendant has presented an extraordinary and compelling reason due to his idiosyncratic circumstances.","cite":"26 F.4th at 27"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"see how a court may be thought to subvert congressional intent by considering nonretroactive changes to the law at the `extraordinary and compelling' stage of the analysis but not while weighing the § 3553(a) factors.","cite":"26 F. 4th 14, 32"}]},{"t":"case","label":"United States v. Smith","cite":"756 F.3d 1179","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1179/","by":{"0":"20, 24, 37","3":"20"},"q":[{"src":"brief","b":0,"text":"Congress knows exactly how to strip district courts of their traditional sentencing discretion when it wishes to do so.","cite":"756 F.3d 1179, 1185-86"},{"src":"brief","b":0,"text":"one of the most conspicuous facts about a defendant.","cite":"756 F.3d at 1180"},{"src":"brief","b":3,"text":"one of the most conspicuous facts about [that] defendant.","cite":"756 F.3d 1179, 1180"}]},{"t":"case","label":"United States v. Tucker","cite":"404 U.S. 443","y":1972,"id":"1971/70-86","sc":1,"by":{"0":"23","3":"8"}},{"t":"case","label":"United States v. Vaughn","cite":"62 F.4th 1071","y":2023,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/62/1071/","by":{"0":"20, 30, 33-34","1":"44","2":"48"},"q":[{"src":"brief","b":0,"text":"a combination of factors may move any given prisoner past it, even if one factor alone does not.","cite":"62 F.4th 1071, 1073"},{"src":"brief","b":0,"text":"‘by itself ’ passes some threshold—to put evidence in compartments and ask whether each compartment suffices.","cite":"62 F.4th at 1072"},{"src":"brief","b":1,"text":"‘by itself’ passes some threshold, put[ting] evidence in compartments and ask[ing] whether each compartment suffices.","cite":"62 F.4th 1071, 1072"}]},{"t":"case","label":"United States v. Washington","cite":"301 F. Supp. 2d 1306","y":2004,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/301/1306/","by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"ha[d] given in his 23 years on the federal bench.","cite":"301 F. Supp. 2d 1306, 1309"}]},{"t":"case","label":"United States v. Watts","cite":"519 U.S. 148","y":1997,"id":"1996/95-1906","sc":1,"by":{"0":"23","3":"3"},"q":[{"src":"brief","b":0,"text":"‘basis for the courts to invent a blanket prohibition against considering certain types of evidence at sentencing.’","cite":"519 U.S. 148, 152"}]},{"t":"case","label":"United States v. Wills","cite":"997 F.3d 685","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/997/685/","by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"‘cannot also be an extraordinary and compelling reason to deviate from that practice.’","cite":"997 F.3d 685, 688"}]},{"t":"case","label":"Viterbo v. Friedlander","cite":"120 U.S. 707","y":1887,"id":"scdb/1886-177","sc":1,"by":{"0":"15"}},{"t":"case","label":"Warden v. Marrero","cite":"417 U.S. 653","y":1974,"id":"1973/73-831","sc":1,"by":{"0":"46"}},{"t":"case","label":"Welch v. Helvering","cite":"290 U.S. 111","y":1933,"id":"scdb/1933-003","sc":1,"by":{"0":"15, 17, 34, 48"}},{"t":"case","label":"Wilkinson v. Garland","cite":"601 U.S. 209","y":2024,"id":"2023/22-666","sc":1,"by":{"0":"17, 48"}},{"t":"case","label":"Williams v. New York","cite":"337 U.S. 241","y":1949,"id":"scdb/1948-087","sc":1,"by":{"0":"25","3":"3"},"q":[{"src":"brief","b":0,"text":"within the limits fixed by law.","cite":"337 U.S. 241, 246"},{"src":"brief","b":3,"text":"[B]efore and since the American colonies became a nation, courts in this country and in England practiced a policy under which a sentencing judge could exercise a wide discretion in the sources and types of evidence used to assist","cite":"337 U.S. 241, 246"}]},{"t":"case","label":"Wisconsin Cent. Ltd. v. United States","cite":"585 U.S. 274","y":2018,"id":"2017/17-530","sc":1,"by":{"0":"14","2":"20"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"0":"39"}},{"t":"usc","label":"9 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/9/1","by":{"0":"39"},"q":[{"src":"argument","who":"Mr. O'Neil","text":"So, in response to public comment during the very robust process that the Sentencing Commission undertook, the Sentencing Commission thought it was necessary to clarify how its guidance in (b)(6) relates to that other guidance, which is set forth separately in Section 1.10."}]},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"0":"1-2, 5-6, 8-11, 13, 32, 34, 36, 38, 41-42, 44","1":"43, 48, 51","2":"7","3":"1, 2, 4, 12, 14, 15, 23","4":"2, 4–6, 11"}},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","subs":["(a)"],"by":{"0":"7, 7","2":"11, 11"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1837","by":{"0":"3, 12, 14, 20-21, 23, 26-29, 46","1":"1, 3, 6, 14, 30, 35, 41","3":"1, 2, 3, 7, 8, 10, 12, 13, 21"}},{"t":"usc","label":"1 U.S.C. § 109","url":"https://www.law.cornell.edu/uscode/text/1/109","by":{"0":"13, 45-46","2":"2, 18, 22"}},{"t":"usc","label":"16 U.S.C. § 472a","url":"https://www.law.cornell.edu/uscode/text/16/472a","subs":["(d)"],"by":{"0":"23"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)","(c)(1)","(c)(1)(A)(ii)","(c)(1)(C)","(c)(1)(D)(ii)","(c)(2000)","(c)(2006)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5-10, 18-19, 24, 30, 36-37, 8, 8, 36, 8","2":"11, 13, 2-5, 8, 11-15, 18, 19, 21-24, 34, 44, 47-49, 8","3":"7, 16, 19","4":"2, 4–5, 10"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(3)","(a)(4)","(a)(6)","(a)(1)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"by":{"0":"9, 12, 23-24, 31, 37, 43, 24, 24, 24","1":"4, 11, 30, 33","2":"19, 36, 37","3":"10, 11, 12, 10, 10, 10"},"q":[{"src":"brief","b":1,"text":"the purposes of sentencing as set forth in","cite":"18 U.S.C. § 3553(a)(2)"},{"src":"brief","b":1,"text":"shorter sentence would be ‘sufficient, but not greater than necessary, to comply with the purposes’ of federal sentencing.","cite":"18 U.S.C. § 3553(a)"}]},{"t":"usc","label":"18 U.S.C. § 3563","url":"https://www.law.cornell.edu/uscode/text/18/3563","subs":["(e)"],"by":{"0":"40"}},{"t":"usc","label":"18 U.S.C. § 3564","url":"https://www.law.cornell.edu/uscode/text/18/3564","subs":["(c)"],"by":{"0":"40"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(a)","(b)","(c)","(c)(1)(A)","(c)(1)(A)(i)","(c)(2)","(d)","(d)(2)(A)","(d)(2)(B)"],"stext":{"head":"§3582. Imposition of a sentence of imprisonment","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Imprisonment.—The court, in determining whether to impose a term of imprisonment, and, if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation. In determining whether to make a recommendation concerning the type of prison facility appropriate for the defendant, the court shall consider any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a)(2)."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to imprisonment can subsequently be—"],[1,"(1) modified pursuant to the provisions of subsection (c);"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."],[0,"(c) Modification of an Imposed Term of Imprisonment.—The court may not modify a term of imprisonment once it has been imposed except that—"],[1,"(1) in any case—"],[2,"(A) the court, upon motion of the Director of the Bureau of Prisons, or upon motion of the defendant after the defendant has fully exhausted all administrative rights to appeal a failure of the Bureau of Prisons to bring a motion on the defendant's behalf or the lapse of 30 days from the receipt of such a request by the warden of the defendant's facility, whichever is earlier, may reduce the term of imprisonment (and may impose a term of probation or supervised release with or without conditions that does not exceed the unserved portion of the original term of imprisonment), after considering the factors set forth in section 3553(a) to the extent that they are applicable, if it finds that—"],[3,"(i) extraordinary and compelling reasons warrant such a reduction; or"],[3,"(ii) the defendant is at least 70 years of age, has served at least 30 years in prison, pursuant to a sentence imposed under section 3559(c), for the offense or offenses for which the defendant is currently imprisoned, and a determination has been made by the Director of the Bureau of Prisons that the defendant is not a danger to the safety of any other person or the community, as provided under section 3142(g);"],[2,"and that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission; and"],[2,"(B) the court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure; and"],[1,"(2) in the case of a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o), upon motion of the defendant or the Director of the Bureau of Prisons, or on its own motion, the court may reduce the term of imprisonment, after considering the factors set forth in section 3553(a) to the extent that they are applicable, if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission."],[0,"(d) Notification Requirements.—"],[1,"(1) Terminal illness defined.—In this subsection, the term \"terminal illness\" means a disease or condition with an end-of-life trajectory."],[1,"(2) Notification.—The Bureau of Prisons shall, subject to any applicable confidentiality requirements—"],[2,"(A) in the case of a defendant diagnosed with a terminal illness—"],[3,"(i) not later than 72 hours after the diagnosis notify the defendant's attorney, partner, and family members of the defendant's condition and inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) not later than 7 days after the date of the diagnosis, provide the defendant's partner and family members (including extended family) with an opportunity to visit the defendant in person;"],[3,"(iii) upon request from the defendant or his attorney, partner, or a family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[3,"(iv) not later than 14 days of receipt of a request for a sentence reduction submitted on the defendant's behalf by the defendant or the defendant's attorney, partner, or family member, process the request;"],[2,"(B) in the case of a defendant who is physically or mentally unable to submit a request for a sentence reduction pursuant to subsection (c)(1)(A)—"],[3,"(i) inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) accept and process a request for sentence reduction that has been prepared and submitted on the defendant's behalf by the defendant's attorney, partner, or family member under clause (i); and"],[3,"(iii) upon request from the defendant or his attorney, partner, or family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[2,"(C) ensure that all Bureau of Prisons facilities regularly and visibly post, including in prisoner handbooks, staff training materials, and facility law libraries and medical and hospice facilities, and make available to prisoners upon demand, notice of—"],[3,"(i) a defendant's ability to request a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) the procedures and timelines for initiating and resolving requests described in clause (i); and"],[3,"(iii) the right to appeal a denial of a request described in clause (i) after all administrative rights to appeal within the Bureau of Prisons have been exhausted."],[1,"(3) Annual report.—Not later than 1 year after December 21, 2018, and once every year thereafter, the Director of the Bureau of Prisons shall submit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report on requests for sentence reductions pursuant to subsection (c)(1)(A), which shall include a description of, for the previous year—"],[2,"(A) the number of prisoners granted and denied sentence reductions, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(B) the number of requests initiated by or on behalf of prisoners, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(C) the number of requests that Bureau of Prisons employees assisted prisoners in drafting, preparing, or submitting, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(D) the number of requests that attorneys, partners, or family members submitted on a defendant's behalf, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(E) the number of requests approved by the Director of the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(F) the number of requests denied by the Director of the Bureau of Prisons and the reasons given for each denial, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(G) for each request, the time elapsed between the date the request was received by the warden and the final decision, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(H) for each request, the number of prisoners who died while their request was pending and, for each, the amount of time that had elapsed between the date the request was received by the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(I) the number of Bureau of Prisons notifications to attorneys, partners, and family members of their right to visit a terminally ill defendant as required under paragraph (2)(A)(ii) and, for each, whether a visit occurred and how much time elapsed between the notification and the visit;"],[2,"(J) the number of visits to terminally ill prisoners that were denied by the Bureau of Prisons due to security or other concerns, and the reasons given for each denial; and"],[2,"(K) the number of motions filed by defendants with the court after all administrative rights to appeal a denial of a sentence reduction had been exhausted, the outcome of each motion, and the time that had elapsed between the date the request was first received by the Bureau of Prisons and the date the defendant filed the motion with the court."],[0,"(e) Inclusion of an Order To Limit Criminal Association of Organized Crime and Drug Offenders.—The court, in imposing a sentence to a term of imprisonment upon a defendant convicted of a felony set forth in chapter 95 (racketeering) or 96 (racketeer influenced and corrupt organizations) of this title or in the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 801 et seq.), or at any time thereafter upon motion by the Director of the Bureau of Prisons or a United States attorney, may include as a part of the sentence an order that requires that the defendant not associate or communicate with a specified person, other than his attorney, upon a showing of probable cause to believe that association or communication with such person is for the purpose of enabling the defendant to control, manage, direct, finance, or otherwise participate in an illegal enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3582?type=usc&year=mostrecent&link-type=html"},"by":{"0":"21, 39-40, 44, 46, 46, 2, 4, 22-23, 40, 1, 3-4, 9, 14, 34, 38-40, 42, 44, 22","2":"25, 6, 6, 6, 6, 6, 6, 6","3":"10, 10, 11, 14, 16, 21, 10"},"q":[{"src":"brief","b":0,"text":"after considering the factors set forth in [18 U.S.C. §] 3553(a) to the extent that they are applicable.","cite":"18 U.S.C. § 3582(c)(1)(A)(i)"},{"src":"brief","b":0,"text":"extraordinary and compelling reasons warrant such a reduction.","cite":"18 U.S.C. § 3582(c)(1)(A)(i)"},{"src":"brief","b":2,"text":"that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission.","cite":"18 U.S.C. 3582(c)(1)(A)"},{"src":"brief","b":2,"text":"court may not modify a term of imprisonment once it has been imposed","cite":"18 U.S.C. 3582(c)"},{"src":"brief","b":3,"text":"Moreover, when the district court’s failure to ‘anticipate developments that take place after the first sentencing’ produces unfairness to the defendant, the Act provides a mechanism for relief","cite":"18 U.S.C. § 3582(c)(1)(A)(i)"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"such a reduction is consistent with applicable policy statements issued by the Sentencing Commission.","cite":"18 U. S. C. § 3582(c)(1)(A)"}]},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(c)","(d)","(e)"],"by":{"0":"40, 40, 24"}},{"t":"usc","label":"18 U.S.C. § 3661","url":"https://www.law.cornell.edu/uscode/text/18/3661","stext":{"head":"§3661. Use of information for sentencing","paras":[[0,"No limitation shall be placed on the information concerning the background, character, and conduct of a person convicted of an offense which a court of the United States may receive and consider for the purpose of imposing an appropriate sentence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3661?type=usc&year=mostrecent&link-type=html"},"by":{"0":"12, 23","3":"2, 3, 8, 9, 10, 14, 15"},"q":[{"src":"brief","b":0,"text":"[n]o limitation shall be placed on the information","cite":"18 U.S.C. § 3661"},{"src":"argument","who":"Mr. Frederick","text":"Section 3661 otherwise imposes \"no limitation on the information a court may receive and consider during sentencing.\" The Third Circuit, however, imposed a judicial limitation on compassionate release."}]},{"t":"usc","label":"18 U.S.C. § 4205","url":"https://www.law.cornell.edu/uscode/text/18/4205","subs":["(g)(1976)","(a)(1982)","(b)(1982)","(g)(1982)"],"by":{"0":"28","2":"29, 30, 29, 30, 29, 30","3":"13, 20"}},{"t":"usc","label":"19 U.S.C. § 1671c","url":"https://www.law.cornell.edu/uscode/text/19/1671c","subs":["(c)(4)(A)"],"by":{"0":"22","3":"7"}},{"t":"usc","label":"19 U.S.C. § 1673c","url":"https://www.law.cornell.edu/uscode/text/19/1673c","subs":["(c)(2)(A)"],"by":{"0":"22"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(a)(1)","(d)","(p)","(t)","(a)","(a)(2)(C)","(a)(2)"],"stext":{"head":"§994. Duties of the Commission","paras":[[0,"(a) The Commission, by affirmative vote of at least four members of the Commission, and pursuant to its rules and regulations and consistent with all pertinent provisions of any Federal statute shall promulgate and distribute to all courts of the United States and to the United States Probation System—"],[1,"(1) guidelines, as described in this section, for use of a sentencing court in determining the sentence to be imposed in a criminal case, including—"],[2,"(A) a determination whether to impose a sentence to probation, a fine, or a term of imprisonment;"],[2,"(B) a determination as to the appropriate amount of a fine or the appropriate length of a term of probation or a term of imprisonment;"],[2,"(C) a determination whether a sentence to a term of imprisonment should include a requirement that the defendant be placed on a term of supervised release after imprisonment, and, if so, the appropriate length of such a term;"],[2,"(D) a determination whether multiple sentences to terms of imprisonment should be ordered to run concurrently or consecutively; and"],[2,"(E) a determination under paragraphs (6) and (11) 1 of section 3563(b) of title 18;"],[1,"(2) general policy statements regarding application of the guidelines or any other aspect of sentencing or sentence implementation that in the view of the Commission would further the purposes set forth in section 3553(a)(2) of title 18, United States Code, including the appropriate use of—"],[2,"(A) the sanctions set forth in sections 3554, 3555, and 3556 of title 18;"],[2,"(B) the conditions of probation and supervised release set forth in sections 3563(b) and 3583(d) of title 18;"],[2,"(C) the sentence modification provisions set forth in sections 3563(c), 3564, 3573, and 3582(c) of title 18;"],[2,"(D) the fine imposition provisions set forth in section 3572 of title 18;"],[2,"(E) the authority granted under rule 11(e)(2) of the Federal Rules of Criminal Procedure to accept or reject a plea agreement entered into pursuant to rule 11(e)(1); and"],[2,"(F) the temporary release provisions set forth in section 3622 of title 18, and the prerelease custody provisions set forth in section 3624(c) of title 18; and"],[1,"(3) guidelines or general policy statements regarding the appropriate use of the provisions for revocation of probation set forth in section 3565 of title 18, and the provisions for modification of the term or conditions of supervised release and revocation of supervised release set forth in section 3583(e) of title 18."],[0,"(b)(1) The Commission, in the guidelines promulgated pursuant to subsection (a)(1), shall, for each category of offense involving each category of defendant, establish a sentencing range that is consistent with all pertinent provisions of title 18, United States Code."],[0,"(2) If a sentence specified by the guidelines includes a term of imprisonment, the maximum of the range established for such a term shall not exceed the minimum of that range by more than the greater of 25 percent or 6 months, except that, if the minimum term of the range is 30 years or more, the maximum may be life imprisonment."],[0,"(c) The Commission, in establishing categories of offenses for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) the grade of the offense;"],[1,"(2) the circumstances under which the offense was committed which mitigate or aggravate the seriousness of the offense;"],[1,"(3) the nature and degree of the harm caused by the offense, including whether it involved property, irreplaceable property, a person, a number of persons, or a breach of public trust;"],[1,"(4) the community view of the gravity of the offense;"],[1,"(5) the public concern generated by the offense;"],[1,"(6) the deterrent effect a particular sentence may have on the commission of the offense by others; and"],[1,"(7) the current incidence of the offense in the community and in the Nation as a whole."],[0,"(d) The Commission in establishing categories of defendants for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, with respect to a defendant, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) age;"],[1,"(2) education;"],[1,"(3) vocational skills;"],[1,"(4) mental and emotional condition to the extent that such condition mitigates the defendant's culpability or to the extent that such condition is otherwise plainly relevant;"],[1,"(5) physical condition, including drug dependence;"],[1,"(6) previous employment record;"],[1,"(7) family ties and responsibilities;"],[1,"(8) community ties;"],[1,"(9) role in the offense;"],[1,"(10) criminal history; and"],[1,"(11) degree of dependence upon criminal activity for a livelihood."],[0,"The Commission shall assure that the guidelines and policy statements are entirely neutral as to the race, sex, national origin, creed, and socioeconomic status of offenders."],[0,"(e) The Commission shall assure that the guidelines and policy statements, in recommending a term of imprisonment or length of a term of imprisonment, reflect the general inappropriateness of considering the education, vocational skills, employment record, family ties and responsibilities, and community ties of the defendant."],[0,"(f) The Commission, in promulgating guidelines pursuant to subsection (a)(1), shall promote the purposes set forth in section 991(b)(1), with particular attention to the requirements of subsection 991(b)(1)(B) for providing certainty and fairness in sentencing and reducing unwarranted sentence disparities."],[0,"(g) The Commission, in promulgating guidelines pursuant to subsection (a)(1) to meet the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code, shall take into account the nature and capacity of the penal, correctional, and other facilities and services available, and shall make recommendations concerning any change or expansion in the nature or capacity of such facilities and services that might become necessary as a result of the guidelines promulgated pursuant to the provisions of this chapter. The sentencing guidelines prescribed under this chapter shall be formulated to minimize the likelihood that the Federal prison population will exceed the capacity of the Federal prisons, as determined by the Commission."],[0,"(h) The Commission shall assure that the guidelines specify a sentence to a term of imprisonment at or near the maximum term authorized for categories of defendants in which the defendant is eighteen years old or older and—"],[1,"(1) has been convicted of a felony that is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46; and"],[1,"(2) has previously been convicted of two or more prior felonies, each of which is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46."],[0,"(i) The Commission shall assure that the guidelines specify a sentence to a substantial term of imprisonment for categories of defendants in which the defendant—"],[1,"(1) has a history of two or more prior Federal, State, or local felony convictions for offenses committed on different occasions;"],[1,"(2) committed the offense as part of a pattern of criminal conduct from which the defendant derived a substantial portion of the defendant's income;"],[1,"(3) committed the offense in furtherance of a conspiracy with three or more persons engaging in a pattern of racketeering activity in which the defendant participated in a managerial or supervisory capacity;"],[1,"(4) committed a crime of violence that constitutes a felony while on release pending trial, sentence, or appeal from a Federal, State, or local felony for which he was ultimately convicted; or"],[1,"(5) committed a felony that is set forth in section 401 or 1010 of the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 841 and 960), and that involved trafficking in a substantial quantity of a controlled substance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/994?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 21, 40, 7, 2, 4, 11, 20-22, 24, 27, 31, 35, 38-39","2":"43, 43, 3, 7, 17, 32, 34, 36, 42, 43, 47","3":"6, 7, 8, 9","4":"17, 24, 26–27"},"q":[{"src":"brief","b":0,"text":"shall describe what should be considered extraordinary and compelling reasons for sentence reduction, including the criteria to be applied and a list of specific examples.","cite":"28 U.S.C. § 994(t)"},{"src":"brief","b":0,"text":"including the criteria to be applied and a list of specific examples.","cite":"28 U.S.C. § 994(t)"},{"src":"brief","b":2,"text":"describe what should be considered extraordinary and compelling reasons","cite":"28 U.S.C. 994(t)"},{"src":"brief","b":2,"text":"consistent with all pertinent provisions of any Federal statute.","cite":"28 U.S.C. 994(a)"},{"src":"brief","b":4,"text":"what should be considered extraordinary and compelling reasons","cite":"28 U.S.C. § 994(t)"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"describe what should be considered extraordinary and compelling reasons for sentence reduction, including the criteria to be applied and a list of specifc examples.","cite":"28 U. S. C. § 994(t)"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"Rehabilitation of the defendant alone shall not be considered an extraordinary and compelling reason.","cite":"28 U. S. C. § 994(t)"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"general policy statements regarding . . . the appropriate use of","cite":"28 U. S. C. § 994(a)(2)(C)"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"by":{"0":"44","2":"11, 18, 44, 4","3":"23"},"q":[{"src":"argument","who":"Mr. Feigin","text":"So you will get the -- some kinds of things that would have been a problem -- that would exhibit the sorts of problems I was mentioning in the last case, where something has to be retroactive in order to qualify as a valid Section 2255 claim."},{"src":"argument","who":"Mr. Feigin","text":"I think this applies to both the cases this morning, both Section 2255 claims and non-retroactive changes in law. There are often cases in which Congress decides to ameliorate sentences going forward."}]},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","subs":["(e)"],"by":{"0":"29","3":"13"}},{"t":"usc","label":"42 U.S.C. § 256","url":"https://www.law.cornell.edu/uscode/text/42/256","subs":["(c)"],"by":{"0":"22","3":"7"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)(6)","(b)"],"by":{"0":"28","3":"13"}},{"t":"reg","label":"Notice, Sentencing Guidelines for United States Courts, 88 Fed. Reg. 28,254","url":"https://www.govinfo.gov/link/fr/88/28254","by":{"0":"6-7, 30","1":"8, 32, 42","2":"9"}},{"t":"case","label":"Batterton v. Francis","cite":"432 U.S. 416","y":1977,"id":"1976/75-1181","sc":1,"by":{"1":"15, 19, 22, 40, 46","2":"32, 33, 42","4":"1, 11, 27"},"q":[{"src":"brief","b":1,"text":"that bears [a] relationship to [a] recognized concept of","cite":"432 U.S. 416, 428"},{"src":"brief","b":1,"text":"‘expressly delegate’ to an agency the authority to give meaning to a particular statutory term.","cite":"432 U.S. at 425"},{"src":"brief","b":4,"text":"bears [a] relationship to [a] recognized concept","cite":"432 U.S. 416, 428"},{"src":"brief","b":4,"text":"that bears no relationship to any recognized concept of","cite":"432 U.S. at 428"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"For example, some statutes `expressly delegat[e]' to an agency the authority to give meaning to a particular statutory term.","cite":"432 U. S. 416, 425"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"simply because it would have interpreted the statute in a different manner.","cite":"432 U. S., at 425"}]},{"t":"case","label":"Braxton v. United States","cite":"500 U.S. 344","y":1991,"id":"1990/90-5358","sc":1,"by":{"1":"4, 8"}},{"t":"case","label":"Brogan v. United States","cite":"522 U.S. 398","y":1998,"id":"1997/96-1579","sc":1,"by":{"1":"48"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"579 U.S. 261","y":2016,"id":"2015/15-446","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"An ‘express and clear conferral of authority’ to an agency ‘does not rest on Chevron’s fiction’ at all. It rests on an express delegation of power to an agency.","cite":"579 U.S. 261, 286"}]},{"t":"case","label":"FCC v. Consumers’ Rsch.","cite":"145 S. Ct. 2428","y":2025,"url":"https://www.courtlistener.com/c/S.%20Ct./145/2428/","sc":1,"by":{"1":"34–35"}},{"t":"case","label":"FCC v. Prometheus Radio Project","cite":"592 U.S. 414","y":2021,"id":"2020/19-1231","sc":1,"by":{"1":"32–33"}},{"t":"case","label":"Gundy v. United States","cite":"588 U.S. 128","y":2019,"id":"2018/17-6086","sc":1,"by":{"1":"25, 34"},"q":[{"src":"brief","b":1,"text":"the power to enact laws restricting the people’s liberty.","cite":"588 U.S. at 154"}]},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"591 U.S. 657","y":2020,"id":"2019/19-431","sc":1,"by":{"1":"33, 47, 49–50","4":"7–8"},"q":[{"src":"brief","b":1,"text":"No party has pressed a constitutional challenge to the breadth of the delegation involved here.","cite":"591 U.S. 657, 679"},{"src":"brief","b":1,"text":"It is a fundamental principle of statutory interpretation that ‘absent provision[s] cannot be supplied by the courts.’","cite":"591 U.S. at 677"},{"src":"brief","b":4,"text":"fundamental principle of statutory interpretation that ‘absent provision[s] cannot be supplied by the courts,’","cite":"591 U.S. 657, 677"},{"src":"argument","who":"Mr. O'Neil","text":"And then, finally, you add on top of that, because you have an express delegation to an agency or, here, to the Commission, Justice Thomas, your opinion in Little Sisters of the Poor made clear that where there is that kind of clear and express delegation, you rewrite the statute, you don't apply it, if you start inferring limitations on that discretion that Congress did not apply."}]},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"by":{"1":"20, 25, 36","2":"32, 41"},"q":[{"src":"brief","b":1,"text":"a term or phrase that leaves agencies with flexibility, such as ‘appropriate’ or ‘reasonable.’","cite":"603 U.S. at 395"},{"src":"brief","b":1,"text":"‘expressly delegate[d]’ to [the Commission] the authority to give meaning to","cite":"603 U.S. at 394"},{"src":"brief","b":2,"text":"Courts must exercise their independent judgment in deciding whether an agency has acted within its statutory authority.","cite":"603 U.S. at 412"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"to exercise a degree of discretion.","cite":"603 U. S. 369, 394"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"ensur[e] the agency has engaged in `rea- Page Proof Pending Publication soned decisionmaking' within those boundaries.","cite":"603 U. S., at 395"},{"src":"argument","who":"Justice Barrett","text":"I just wanted to ask you about your Loper Bright point and the degree of discretion that the Sentencing Commission does here -- has here. Am I -- I'm going to state it, and then you tell me if I'm understanding your point correctly."},{"src":"argument","who":"Justice Barrett","text":"Your point about Loper Bright is that that discretion has to happen between certain goalposts, and the fact that the First Step Act has imposed a rule of non-retroactivity means that the Commission has exceeded the limits on its authority."}]},{"t":"case","label":"Pickens v. Hamilton-Ryker IT Sols., LLC","cite":"133 F.4th 575","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/133/575/","by":{"1":"21, 31, 33"},"q":[{"src":"brief","b":1,"text":"An ‘express and clear conferral of authority’ to an agency ‘does not rest on Chevron’s fiction’ at all. It rests on an express delegation of power to an agency.","cite":"133 F.4th 575, 587"},{"src":"brief","b":1,"text":"determine the scope of the agency’s discretion under the statute by setting out the task that the agency must perform.","cite":"133 F.4th at 588"}]},{"t":"case","label":"Stinson v. United States","cite":"508 U.S. 36","y":1993,"id":"1992/91-8685","sc":1,"by":{"1":"18, 21, 35"},"q":[{"src":"brief","b":1,"text":"by virtue of an express congressional delegation of authority for rulemaking.","cite":"508 U.S. at 44"}]},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"by":{"1":"47"},"q":[{"src":"brief","b":1,"text":"fail to overcome the clear statutory language,","cite":"585 U.S. 667, 684"}]},{"t":"case","label":"United States v. Dupree","cite":"57 F.4th 1269","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/57/1269/","by":{"1":"27–28"}},{"t":"case","label":"United States v. Galante","cite":"111 F.3d 1029","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/111/1029/","by":{"1":"26"}},{"t":"case","label":"United States v. Jackson","cite":"964 F.3d 197","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/964/197/","by":{"1":"50"}},{"t":"case","label":"United States v. LaBonte","cite":"520 U.S. 751","y":1997,"id":"1996/95-1726","sc":1,"by":{"1":"4, 35, 37–38, 47","2":"43, 44","4":"26"}},{"t":"case","label":"United States v. McCoy","cite":"981 F.3d 271","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/981/271/","by":{"1":"17, 51","2":"31"},"q":[{"src":"brief","b":1,"text":"about Congress’s paired First Step Act judgments: that not all defendants convicted under § 924(c) should receive new sentences, but that the courts should be empowered to relieve some defendants of those sentences on a case-by-case basis.","cite":"981 F.3d 271, 286–87"},{"src":"brief","b":1,"text":"[T]here is a significant difference between automatic vacatur and resentencing of an entire class of sentences . . . and allowing for the provision of individual relief in the most grievous cases.","cite":"981 F.3d at 286"}]},{"t":"case","label":"United States v. Rutherford","cite":"120 F.4th 360","y":2024,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/120/360/","by":{"1":"50"}},{"t":"case","label":"United States v. Sprei","cite":"145 F.3d 528","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/145/528/","by":{"1":"44"}},{"t":"case","label":"United States v. Vargas","cite":"74 F.4th 673","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/74/673/","by":{"1":"28"},"q":[{"src":"brief","b":1,"text":"[i]nstead of addressing the public, as agencies do, the Commission addresses federal judges.","cite":"74 F.4th 673, 83"}]},{"t":"case","label":"United States v. Veliz","cite":"2024 WL 4475055","y":2024,"court":"S.D. Fla. Oct. 11","by":{"1":"42"}},{"t":"case","label":"Wayman v. Southard","cite":"10 Wheat. 1","y":1825,"url":"https://www.courtlistener.com/c/Wheat./10/1/","by":{"1":"20, 24–25"}},{"t":"case","label":"White Stallion Energy Ctr., LLC v. EPA","cite":"748 F.3d 1222","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/748/1222/","by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"assigned EPA, not the courts, to make many discretionary calls","cite":"748 F.3d 1222, 1266"}]},{"t":"case","label":"Whitman v. Am. Trucking Ass’n","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"the degree of agency discretion that is acceptable varies according to the scope of the power congressionally conferred","cite":"531 U.S. 457, 475"}]},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","by":{"1":"39"}},{"t":"usc","label":"28 U.S.C. § 991","url":"https://www.law.cornell.edu/uscode/text/28/991","subs":["(b)","(b)(1)(B)"],"by":{"1":"4, 30, 33","2":"6, 34"},"q":[{"src":"brief","b":1,"text":"reflect[ing] . . . advancement in knowledge of human behavior as it relates to the criminal justice process.","cite":"28 U.S.C. § 991(b)(1)"}]},{"t":"reg","label":"87 Fed. Reg. 60438","url":"https://www.govinfo.gov/link/fr/87/60438","by":{"1":"7"}},{"t":"reg","label":"88 Fed. Reg. 7180","url":"https://www.govinfo.gov/link/fr/88/7180","by":{"1":"32","4":"5"}},{"t":"case","label":"Br. for the United States in Opp’n, Jarvis v. United States","cite":"2021 WL 5864543","y":2021,"court":"U.S. Dec. 8","by":{"1":"7, 38","4":"4"}},{"t":"case","label":"Brown v. United States","cite":"2005 WL 1330726","y":2005,"court":"S.D. Ga. May 9","by":{"2":"30"}},{"t":"case","label":"Brown v. United States","cite":"602 U.S. 101","y":2024,"id":"2023/22-6389","sc":1,"by":{"2":"38"},"q":[{"src":"brief","b":2,"text":"[l]enity applies only if a statute remains grievously ambiguous after [the Court] ha[s] consulted everything from which aid can be derived.","cite":"602 U.S. 101, 122"}]},{"t":"case","label":"Edwards v. Vannoy","cite":"593 U.S. 255","y":2021,"id":"2020/19-5807","sc":1,"by":{"2":"2, 18"}},{"t":"case","label":"Hewitt v. United States","cite":"145 S. Ct. 2165","y":2025,"id":"2024/23-1002","sc":1,"by":{"2":"3, 16, 18, 19, 21-24, 49","4":"5"},"q":[{"src":"brief","b":2,"text":"offenders with final sentences * * * stuck with their old sentences,","cite":"145 S. Ct. 2165, 2177"},{"src":"brief","b":2,"text":"eliminated 25-year stacked sentences for first-time § 924(c) offenders.","cite":"145 S. Ct. at 2176"},{"src":"argument","who":"Mr. Feigin","text":"But, in enacting those very changes, Congress made a categorical judgment to, in the words of the principal opinion in Hewitt, leave Section 1924(c) offenders with final sentences stuck with their old sentences."},{"src":"argument","who":"Mr. Feigin","text":"Well, I think this is a direct attack on what Congress did because Congress drew a categorical line, and, as the principal opinion in Hewitt recognized, that was partly to prevent all the relitigation concerns."}]},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"by":{"2":"31"}},{"t":"case","label":"Koons v. United States","cite":"584 U.S. 700","y":2018,"id":"2017/17-5716","sc":1,"by":{"2":"43"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"by":{"2":"42"}},{"t":"case","label":"Monsalvo v. Bondi","cite":"145 S. Ct. 1232","y":2025,"id":"2024/23-929","sc":1,"by":{"2":"28"}},{"t":"case","label":"Neal v. United States","cite":"516 U.S. 284","y":1996,"id":"1995/94-9088","sc":1,"by":{"2":"6, 44, 45"},"q":[{"src":"brief","b":2,"text":"eliminate unwarranted disparities in punishment of similar defendants who commit similar crimes.","cite":"516 U.S. 284, 290-291"}]},{"t":"case","label":"Perdue v. Kenny A. ex rel. Winn","cite":"559 U.S. 542","y":2010,"id":"2009/08-970","sc":1,"by":{"2":"42"}},{"t":"case","label":"Quarles v. United States","cite":"587 U.S. 645","y":2019,"id":"2018/17-778","sc":1,"by":{"2":"26"},"q":[{"src":"brief","b":2,"text":"should not lightly conclude that Congress enacted a self-defeating statute,","cite":"587 U.S. 645, 654"}]},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"by":{"2":"35"}},{"t":"case","label":"Tanzin v. Tanvir","cite":"592 U.S. 43","y":2020,"id":"2020/19-71","sc":1,"by":{"2":"42"}},{"t":"case","label":"Terry v. United States","cite":"593 U.S. 486","y":2021,"id":"2020/20-5904","sc":1,"by":{"2":"4, 44"}},{"t":"case","label":"United States v. Bricker","cite":"135 F.4th 427","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/135/427/","by":{"2":"38"},"q":[{"src":"brief","b":2,"text":"Rehabilitation alone is not the only congressionally imposed limit; it is a specific limit within the principal limit that the reason must be ‘extraordinary and compelling.’","cite":"135 F.4th 427, 444-445"}]},{"t":"case","label":"United States v. Crandall","cite":"25 F.4th 582","y":2022,"url":"https://www.courtlistener.com/c/F.4th/25/582/","by":{"2":"20"},"q":[{"src":"brief","b":2,"text":"for reducing a sentence imposed years ago.","cite":"25 F.4th 582, 586"}]},{"t":"case","label":"United States v. Fulton","cite":"2024 WL 4503467","y":2024,"court":"E.D. La. Oct. 16","by":{"2":"45"},"q":[{"src":"brief","b":2,"text":"arrived at different conclusions from the same sentencing disparity.","cite":"2024 WL 4503467"}]},{"t":"case","label":"United States v. Havener","cite":"905 F.2d 3","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/905/3/","by":{"2":"30"}},{"t":"case","label":"United States v. Howard","cite":"2024 WL 112010","y":2024,"court":"D. Md. Jan. 10","by":{"2":"48"}},{"t":"case","label":"United States v. Jenkins","cite":"50 F.4th 1185","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/50/1185/","by":{"2":"24-27"},"q":[{"src":"brief","b":2,"text":"remained appropriate for defendants already sentenced,","cite":"50 F.4th 1185, 1199"},{"src":"brief","b":2,"text":"in only two narrow circumstances—(a) on remand from a court of appeals, or (b) to reflect a defendant’s substantial assistance to the government, upon a government motion filed within one year of the sentence.","cite":"50 F.4th at 1201"}]},{"t":"case","label":"United States v. Martin","cite":"2025 WL 1728694","y":2025,"court":"W.D. Va. June 20","by":{"2":"48"}},{"t":"case","label":"United States v. Smith","cite":"650 F.2d 206","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/650/206/","by":{"2":"25"},"q":[{"src":"brief","b":2,"text":"if, on further reflection, the original sentence now seem[ed] unduly harsh,","cite":"650 F.2d 206, 208"}]},{"t":"case","label":"United States v. Wesley","cite":"60 F.4th 1277","y":2023,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/60/1277/","by":{"2":"27","3":"21"}},{"t":"law","label":"Pub. L. No. 105-386","url":"https://www.govinfo.gov/link/plaw/105/public/386","by":{"2":"8"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","subs":["(b)(1)"],"by":{"2":"6","3":"10"}},{"t":"usc","label":"18 U.S.C. § 4042","url":"https://www.law.cornell.edu/uscode/text/18/4042","subs":["(a)"],"by":{"2":"27"}},{"t":"usc","label":"28 U.S.C. § 4205","url":"https://www.law.cornell.edu/uscode/text/28/4205","subs":["(g)"],"by":{"2":"29, 30"}},{"t":"reg","label":"59 Fed. Reg. 1238","url":"https://www.govinfo.gov/link/fr/59/1238","by":{"2":"30"}},{"t":"case","label":"Chavez-Meza v. United States","cite":"585 U.S. 109","y":2018,"id":"2017/17-5639","sc":1,"by":{"3":"10"}},{"t":"case","label":"Continental Ore Co. v. Union Carbide & Carbon Corp.","cite":"370 U.S. 690","y":1962,"id":"1961/304","sc":1,"by":{"3":"5"},"q":[{"src":"brief","b":3,"text":"wip[e] the slate clean after scrutiny of each.","cite":"370 U.S. 690, 698-99"}]},{"t":"case","label":"CPSC v. GTE Sylvania, Inc.","cite":"447 U.S. 102","y":1980,"id":"1979/79-521","sc":1,"by":{"3":"17"},"q":[{"src":"brief","b":3,"text":"the views of a subsequent Congress form a hazardous basis for inferring the intent of an earlier one.","cite":"447 U.S. 102, 117"}]},{"t":"case","label":"Rainwater v. United States","cite":"356 U.S. 590","y":1958,"id":"1957/276","sc":1,"by":{"3":"17"}},{"t":"case","label":"Solem v. Helm","cite":"463 U.S. 277","y":1983,"id":"1982/82-492","sc":1,"by":{"3":"8"},"q":[{"src":"brief","b":3,"text":"the normal expectation in the vast majority of cases.","cite":"463 U.S. 277, 300"}]},{"t":"case","label":"Truck Ins. Exch. v. Kaiser Gypsum Co.","cite":"602 U.S. 268","y":2024,"id":"2023/22-1079","sc":1,"by":{"3":"23"}},{"t":"case","label":"Turkiye Halk Bankasi A.S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"by":{"3":"22"}},{"t":"case","label":"United States v. Banks","cite":"428 F. Supp. 1088","y":1977,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp./428/1088/","by":{"3":"20"}},{"t":"case","label":"United States v. Hymes","cite":"19 F.4th 928","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/19/928/","by":{"3":"8"}},{"t":"case","label":"United States v. Uriarte","cite":"975 F.3d 596","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/975/596/","by":{"3":"10"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"by":{"3":"21"}},{"t":"usc","label":"18 U.S.C. § 3621","url":"https://www.law.cornell.edu/uscode/text/18/3621","subs":["(b)"],"by":{"3":"21"}},{"t":"usc","label":"18 U.S.C. § 3742","url":"https://www.law.cornell.edu/uscode/text/18/3742","subs":["(g)"],"by":{"3":"7"}},{"t":"rule","label":"Fed. R. Crim. P. 35","url":"https://www.law.cornell.edu/rules/frcrmp/rule_35","subs":["(b)"],"by":{"3":"21","4":"18–19"}},{"t":"case","label":"King v. Burwell","cite":"576 U.S. 473","y":2015,"id":"2014/14-114","sc":1,"by":{"4":"28"}},{"t":"case","label":"Seven Cnty. Infrastructure Coal. v. Eagle Cnty.","cite":"145 S. Ct. 1497","y":2025,"id":"2024/23-975","sc":1,"by":{"4":"27"}},{"t":"case","label":"Torres v. Lynch","cite":"578 U.S. 452","y":2016,"id":"2015/14-1096","sc":1,"by":{"4":"24"}},{"t":"case","label":"United States v. Bryant","cite":"996 F.3d 1243","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/996/1243/","by":{"4":"14"}},{"t":"case","label":"United States v. Ellenbogen","cite":"390 F.2d 537","y":1968,"court":"2d. Cir.","url":"https://www.courtlistener.com/c/F.2d/390/537/","by":{"4":"18"},"q":[{"src":"brief","b":4,"text":"an opportunity to reconsider the sentence in the light of any further information about the defendant or the case.","cite":"390 F.2d 537, 543"}]},{"t":"case","label":"United States v. Gee","cite":"56 F.R.D. 377","y":1972,"court":"S.D. Tex.","url":"https://www.courtlistener.com/c/F.R.D./56/377/","by":{"4":"18"}},{"t":"case","label":"United States v. Jean","cite":"108 F.4th 275","y":2024,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/108/275/","by":{"4":"17"}},{"t":"case","label":"Weinberger v. Hynson, Westcott & Dunning, Inc.","cite":"412 U.S. 609","y":1973,"id":"1972/72-394","sc":1,"by":{"4":"6"},"q":[{"src":"brief","b":4,"text":"the most harmonious, comprehensive meaning possible in light of the legislative policy and purpose.","cite":"412 U.S. 609, 631–32"}]},{"t":"case","label":"Whitfield v. United States","cite":"543 U.S. 209","y":2005,"id":"2004/03-1293","sc":1,"by":{"4":"7"}},{"t":"reg","label":"28 C.F.R. § 572.40","url":"https://www.ecfr.gov/current/title-28/section-572.40","subs":["(a)"],"by":{"4":"19"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"4":"10"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"4":"10"}}]};